function expectKnown(objects: object[], known: readonly string[], what: string, optional = false): void {
  if (!optional) expect(objects.length, `no ${what} in the fixture`).toBeGreaterThan(0);
  for (const object of objects) {
    const unknown = Object.keys(object).filter((k) => !known.includes(k));
    expect(unknown, `${what} keys the viewer's type does not know`).toEqual([]);
  }
}

describe("real API responses use only fields the viewer's types know", () => {
  it("/api/repo", () => {
    expectKnown([repo], REPO_KEYS, "repo");
    expectKnown(repo.sheets, SHEET_KEYS, "sheet");
    expect(repo.sheets.map((s) => s.kind)).toEqual(["bfd", "pfd"]);
    expect(repo.sheets.every((s) => s.generator === "flowsheet" && s.status === "drafted")).toBe(true);
  });

  it("/api/tree", () => {
    expectKnown(tree, TREE_KEYS, "tree entry");
    // The ASU's datasheets and layout files (the layout view links them).
    expectKnown(asuTreeJson as unknown as TreeEntry[], TREE_KEYS, "ASU tree entry");
  });

  it("/api/streams", () => {
    expectKnown([table], TABLE_KEYS, "stream table");
    expectKnown(table.streams, STREAM_KEYS, "stream");
    expectKnown(
      table.streams.flatMap((s) => (s.composition ? [s.composition] : [])),
      COMPOSITION_KEYS,
      "composition",
    );
    expectKnown(table.balances, BALANCE_KEYS, "balance");
    expectKnown(table.nodes, NODE_KEYS, "node");
    expect(table.tolerance).toEqual({ abs: expect.any(Number), rel: expect.any(Number) });
  });

  it("/api/yaml of the flowsheet", () => {
    expectKnown([yamlDoc], YAML_KEYS, "yaml doc");
    expect(yamlDoc.kind).toBe("flowsheet");
  });

  it("/api/validate", () => {
    expectKnown([validation], REPORT_KEYS, "validation report");
    expectKnown(validation.findings, FINDING_KEYS, "finding");
    // The flowsheet changed after the sheets were built.
    expect(validation.findings.map((f) => f.rule)).toContain("cheme.generated-outdated");
    for (const f of validation.findings) expect(f.id).toMatch(new RegExp(`^${f.file.replace(/[.]/g, "\\.")}#`));
  });

  it("/api/impact", () => {
    expectKnown([impact], IMPACT_KEYS, "impact report");
    expectKnown(impact.findings, FINDING_KEYS, "finding");
    expect(impact.commit).toMatch(/^[0-9a-f]{40}$/);
    expect(new Set(impact.findings.map((f) => [f.level, f.rule].join(" ")))).toEqual(
      new Set(["info cheme.review-needed"]),
    );
    expect(impact.findings.map((f) => f.file)).toEqual(["process/BFD.xml", "process/PFD.xml"]);
  });

  it("/api/diff of a rebuilt BFD", () => {
    expectKnown([diff], DIFF_KEYS, "sheet diff");
    expectKnown(diff.changes, CHANGE_KEYS, "change");
    for (const c of diff.changes) if (c.item) expect(diff.items?.[c.item]).toEqual({ class: expect.any(String), tag: expect.any(String) });
  });

  it("/api/layout", () => {
    expectKnown([layout], LAYOUT_KEYS, "layout");
    expectKnown(layout.lines ?? [], LINE_KEYS, "line route");
    expectKnown(layout.findings, FINDING_KEYS, "finding");
  });

  it("/api/layout of the ASU, with its generated model", () => {
    expectKnown([asu], LAYOUT_KEYS, "layout");
    expectKnown(asu.equipment, PLACED_KEYS, "placed equipment");
    expectKnown(asu.findings, FINDING_KEYS, "finding");
    expectKnown(asu.model_findings ?? [], FINDING_KEYS, "model finding");
    expectKnown(asu.separations ?? [], SEPARATION_KEYS, "separation", true);
    const model = asu.model!;
    expectKnown([model], [...MODEL_KEYS, ...MEP_MODEL_KEYS], "model");
    // Every section of the contract is there, cabling and HVAC too (the ASU has an electrical
    // list and layout/hvac.yaml since process-library#2).
    expect(Object.keys(model).sort()).toEqual([...MODEL_KEYS, ...MEP_MODEL_KEYS].sort());
    expectKnown(model.tray_tiers ?? [], TRAY_TIER_KEYS, "tray tier");
    expectKnown(model.trays ?? [], TRAY_KEYS, "tray");
    expectKnown(model.junction_boxes ?? [], JB_KEYS, "junction box");
    expectKnown(model.cables ?? [], CABLE_KEYS, "cable");
    expectKnown([model.cabling!], CABLING_KEYS, "cabling");
    expectKnown(model.hvac_units ?? [], HVAC_UNIT_KEYS, "hvac unit");
    expectKnown(model.hvac_rooms ?? [], HVAC_ROOM_KEYS, "hvac room");
    expectKnown(model.ducts ?? [], DUCT_KEYS, "duct");
    expectKnown([model.hvac!], HVAC_KEYS, "hvac");
    expectKnown([model.provenance], PROVENANCE_KEYS, "provenance");
    expectKnown([model.site!], MODEL_SITE_KEYS, "model site");
    expectKnown(model.areas, MODEL_AREA_KEYS, "model area");
    expectKnown(model.roads, MODEL_ROAD_KEYS, "model road");
    expectKnown(model.racks, MODEL_RACK_KEYS, "model rack");
    expectKnown(model.buildings, MODEL_BUILDING_KEYS, "model building");
    expectKnown(model.buildings.flatMap((b) => b.levels), MODEL_LEVEL_KEYS, "model level");
    expectKnown(model.buildings.flatMap((b) => b.openings), OPENING_KEYS, "building opening", true);
    expectKnown(model.equipment, MODEL_EQUIPMENT_KEYS, "model equipment");
    expectKnown(model.pipes, PIPE_KEYS, "pipe");
    expectKnown(model.pipes.flatMap((p) => (p.class ? [p.class] : [])), PIPE_CLASS_KEYS, "pipe class");
    expectKnown(model.inline, INLINE_KEYS, "in-line item");
    expectKnown(model.structures, STRUCTURE_KEYS, "structure");
    expectKnown(model.structures.flatMap((s) => s.levels), STRUCTURE_LEVEL_KEYS, "structure level");
    const stairs = model.structures.flatMap((s) => s.stairs);
    const ladders = [...model.structures.flatMap((s) => s.ladders), ...model.platforms.map((p) => p.ladder), ...model.racks.flatMap((r) => r.ladders ?? [])];
    expectKnown(stairs, STAIR_KEYS, "stair");
    expectKnown(ladders, LADDER_KEYS, "ladder");
    expectKnown(model.platforms, PLATFORM_KEYS, "platform");
    expectKnown(model.supports ?? [], SUPPORT_KEYS, "support");
    expectKnown(model.step_overs ?? [], STEP_OVER_KEYS, "step-over");
    // The ASU declares its casing openings (process-library#4), and since its D-046 AIR-2002
    // enters CB-1 through its declared opening again: no penetration. The shape comes from a
    // copy without AIR-2002 (layout-asu-penetration.json).
    expectKnown(model.penetrations ?? [], PENETRATION_KEYS, "penetration", true);
    expect((model.support_steel ?? []).length).toBeGreaterThan(0);
    expectKnown(model.support_steel ?? [], SUPPORT_STEEL_KEYS, "support steel");
    const penetrations = (penetrationJson as unknown as { model: LayoutModel }).model.penetrations ?? [];
    expectKnown(penetrations, PENETRATION_KEYS, "penetration");
    expectKnown(penetrations.map((p) => p.opening), OPENING_KEYS, "penetration opening");
    expectKnown((penetrationJson as unknown as { model_findings: Finding[] }).model_findings, FINDING_KEYS, "penetration finding");
    expect(model.supports?.length).toBeGreaterThan(0);
    expectKnown(model.zones, ZONE_KEYS, "zone");
    expectKnown(model.zones.flatMap((z) => z.volumes), VOLUME_KEYS, "zone volume");
    expectKnown(asu.zones ?? [], ZONE_KEYS, "zone (top level)");
    expect(asu.zones).toEqual(model.zones);
    expectKnown(model.unrouted, UNROUTED_KEYS, "unrouted");
    expectKnown([model.routing], ROUTING_KEYS, "routing");
    expectKnown(model.routing.rack_fill, RACK_FILL_KEYS, "rack fill");
    expect(model.routing).toMatchObject({ segments: 218, routed: 214, unrouted: 4 });
    expect(model.unrouted).toHaveLength(model.routing.unrouted);
    // Every route says why; the summary counts the reasons and the battery limits.
    expect(model.pipes.filter((p) => !p.reason).map((p) => p.id)).toEqual([]);
    for (const reason of new Set(model.pipes.map((p) => p.reason!))) expect(model.routing.reasons, reason).toHaveProperty([reason]);
    expect(Object.values(model.routing.battery_limits ?? {}).every((n) => n > 0)).toBe(true);
    // A component two segments share comes once, with both segments in its refs.
    expect(new Set(model.inline.map((i) => i.id)).size).toBe(model.inline.length);
    expect(model.inline.some((i) => (i.refs.segments?.length ?? 0) > 1)).toBe(true);

    // Every part, wherever it sits, has the part fields, a known kind and material.
    const parts = [
      ...model.equipment.flatMap((e) => e.parts),
      ...model.racks.flatMap((r) => r.parts),
      ...model.buildings.flatMap((b) => b.parts),
      ...model.structures.flatMap((s) => [...s.parts, ...s.walls]),
      ...stairs.flatMap((s) => s.parts),
      ...ladders.flatMap((l) => l.parts),
      ...model.platforms.flatMap((p) => p.parts),
      ...model.areas.flatMap((a) => a.parts ?? []),
      ...model.pipes.flatMap((p) => p.parts ?? []),
      ...model.inline.flatMap((i) => i.parts ?? []),
      ...(model.supports ?? []).flatMap((s) => s.parts),
      ...(model.step_overs ?? []).flatMap((s) => s.parts),
    ];
    expectKnown(parts, PART_KEYS, "part");
    expect([...new Set(parts.map((p) => p.kind))].filter((k) => !PART_KINDS.includes(k))).toEqual([]);
    expect([...new Set(parts.map((p) => p.material))].filter((m) => !PART_MATERIALS.includes(m))).toEqual([]);
    // The new kinds and materials are all in use.
    for (const kind of ["member", "annulus"]) expect(parts.some((p) => p.kind === kind), kind).toBe(true);
    for (const material of ["grating", "handrail", "cage"]) expect(parts.some((p) => p.material === material), material).toBe(true);

    const nozzles = model.equipment.flatMap((e) => e.nozzles);
    const envelopes = model.equipment.flatMap((e) => e.envelopes);
    expectKnown(nozzles, NOZZLE_KEYS, "nozzle");
    expectKnown(envelopes, ENVELOPE_KEYS, "envelope");
    // Declared operators: on in-line valves and on transmitter tappings, of the four kinds.
    const operators = [...model.inline, ...nozzles].flatMap((o) => (o.operator ? [o.operator] : []));
    expectKnown(operators, OPERATOR_KEYS, "operator");
    expect(new Set(operators.map((o) => o.kind))).toEqual(new Set(["chainwheel", "extension_spindle", "remote_operator", "remote_mount"]));
    expect(nozzles.filter((n) => n.operator).every((n) => n.operator!.kind === "remote_mount")).toBe(true);
    const objects = [
      model.site!,
      ...model.areas,
      ...model.roads,
      ...model.racks,
      ...model.buildings,
      ...model.equipment,
      ...parts,
      ...nozzles,
      ...envelopes,
      ...model.pipes,
      ...model.inline,
      ...model.structures,
      ...stairs,
      ...ladders,
      ...model.platforms,
      ...model.zones,
    ];
    expectKnown(objects.map((o) => o.refs), REFS_KEYS, "refs");
    for (const o of objects) expect(["generated", "pinned", "declared"], o.id).toContain(o.source);
    for (const v of model.zones.flatMap((z) => z.volumes)) expect(["generated", "pinned", "declared"]).toContain(v.source);
    // Model findings name the model file and carry a 3D box.
    for (const f of asu.model_findings ?? []) {
      expect(f.file).toBe("layout/plant-model.yaml");
      expect(f.box).toHaveLength(6);
    }
  });
});

