const SIMULATION_KEYS: (keyof SimulationView)[] = ["rev", "file", "run_file", "case", "cases", "spec", "run", "stale", "staleness", "units", "problem", "findings"];
const SIM_SPEC_KEYS: (keyof SimulationView["spec"])[] = ["simulator", "property_package", "components", "tolerance", "tear_streams", "exclude", "guesses", "specs"];
const SIM_UNIT_KEYS: (keyof SimulationUnit)[] = ["id", "unit", "status", "reason", "spec", "run", "basis"];
const SIM_RUN_KEYS: (keyof SimulationRun)[] = [
  "case",
  "run_at",
  "tool",
  "simulator",
  "property_package",
  "model_fingerprint",
  "inputs",
  "converged",
  "status",
  "iterations",
  "messages",
  "units",
  "streams",
  "findings",
  "energy",
];
const SIM_RUN_UNIT_KEYS: (keyof SimRunUnit)[] = ["id", "unit", "status", "converged", "results", "messages", "warnings", "reason", "basis", "coupling"];
const SIM_RUN_STREAM_KEYS: (keyof SimRunStream)[] = ["id", "values", "filled", "kept"];

describe("real /api/simulation", () => {
  const asu = simulationAsuJson as unknown as SimulationView;
  const current = simulationRunJson as unknown as SimulationView;
  const stale = simulationStaleJson as unknown as SimulationView;
  const failed = simulationFailedJson as unknown as SimulationView;
  const all = [asu, current, stale, failed];

  it("uses only fields the viewer's types know", () => {
    expectKnown(all, SIMULATION_KEYS, "simulation");
    expectKnown(all.map((v) => v.spec), SIM_SPEC_KEYS, "simulation spec");
    expectKnown(all.flatMap((v) => v.units), SIM_UNIT_KEYS, "simulation unit");
    expectKnown(all.map((v) => v.staleness), ["model_fingerprint", "current_fingerprint", "changed_files"], "staleness");
    const runs = [current.run!, stale.run!, failed.run!];
    expectKnown(runs, SIM_RUN_KEYS, "simulation run");
    expectKnown(runs.flatMap((r) => r.units), SIM_RUN_UNIT_KEYS, "run unit");
    expectKnown(current.run!.streams, SIM_RUN_STREAM_KEYS, "run stream");
    expectKnown(runs.map((r) => r.inputs), ["commit", "dirty", "fingerprints"], "run inputs");
    expectKnown(runs.map((r) => r.simulator), ["name", "version", "method"], "run simulator");
    expectKnown([...asu.findings, ...failed.run!.findings], FINDING_KEYS, "finding");
  });

  it("the ASU: no run, excluded units with their reason, nested specs", () => {
    expect(asu.run).toBeNull();
    expect(asu.stale).toBeNull();
    expect(asu.spec.exclude).toEqual(["PUR", "E3101", "KT3101", "X3101", "C1102"]);
    const byId = new Map(asu.units.map((u) => [u.id, u]));
    expect(byId.get("PUR")).toMatchObject({ status: "excluded", reason: "exclude: in process/simulation.yaml" });
    expect(byId.get("V2101")?.reason).toBe("inside PUR, excluded in process/simulation.yaml");
    expect(byId.get("C3101")?.status).toBe("simulated");
    expect(byId.get("C3101")?.spec?.side_draws).toBeTruthy();
  });

  it("a recorded run: current, then stale, and one that did not converge", () => {
    expect(current.stale).toBe(false);
    expect(current.run?.converged).toBe(true);
    expect(current.run?.iterations).toBe(1); // the stand-in solver reports one
    expect(current.run?.simulator).toMatchObject({ name: "dwsim", version: "9.0.5.0" });
    expect(stale.stale).toBe(true);
    expect(stale.staleness.changed_files).toEqual(["process/simulation.yaml"]);
    expect(failed.run?.converged).toBe(false);
    expect(failed.run?.streams).toEqual([]);
    expect(failed.units.find((u) => u.id === "E1")?.run?.converged).toBe(false);
  });

  it("the stream table after the fill holds the run's values", () => {
    const table = streamsSimulationJson as unknown as StreamTable;
    expectKnown(table.streams, STREAM_KEYS, "stream");
    for (const s of current.run!.streams)
      for (const field of s.filled) {
        const row = table.streams.find((t) => t.id === s.id)!;
        const value = field === "composition" ? row.composition : row.properties[field as "pressure"];
        expect(value?.provenance, `${s.id} ${field}`).toBe("calculated");
      }
  });
});

