describe("real /api/reactions of core's ammonia example", () => {
  const view = reactionsJson as unknown as ReactionsView;
  const unbalanced = reactionsUnbalancedJson as unknown as ReactionsView;
  it("uses only fields the viewer's types know", () => {
    for (const v of [view, unbalanced]) {
      expectKnown([v], REACTIONS_KEYS, "reactions");
      expectKnown(v.reactions, REACTION_KEYS, "reaction");
      expectKnown(v.reactions.flatMap((r) => r.units), PLACE_KEYS, "reaction place");
      expectKnown(v.reactions.map((r) => r.heat_of_reaction!), HEAT_KEYS, "heat of reaction");
      expectKnown(v.reactions.map((r) => r.element_balance), ["evaluable", "balanced", "change"], "element balance");
      expectKnown(v.reactors, REACTOR_KEYS, "reactor");
      expectKnown(v.reactors.flatMap((r) => r.reactions), ["id", "extent_kmol_h", "heat_of_reaction_kJ_kmol", "ln_k", "ln_q_over_k", "rate", "rate_unit"], "reactor reaction");
      expectKnown(v.balance.balances, [...BALANCE_KEYS, "extents_kmol_h"], "reactive balance");
      expect(Object.keys(v.balance)).toEqual(["balances", "findings"]);
    }
    expectKnown(unbalanced.balance.findings, FINDING_KEYS, "finding");
  });
  it("one equilibrium reaction in R1, balanced; unbalanced with its findings", () => {
    expect(view.kinetics?.catalysts.map((c) => c.id)).toEqual(["FE_NH3"]);
    expect(view.reactions[0]?.rate).toBeNull();
    expect(view.reactors.every((r) => r.bed === null)).toBe(true);
    expect(view.reactions.map((r) => r.id)).toEqual(["NH3_SYN"]);
    expect(view.reactions[0]?.element_balance).toEqual({ evaluable: true, balanced: true, change: {} });
    expect(view.reactors.map((r) => r.node)).toEqual(["LOOP", "R1"]);
    expect(view.reactors[1]?.model).toBe("equilibrium");
    expect(view.balance.findings).toEqual([]);
    expect(unbalanced.reactions[0]?.element_balance.change).toEqual({ N: 1, H: 3 });
    expect(unbalanced.balance.findings.map((f) => f.rule)).toContain("cheme.reaction-element-balance");
    const table = streamsAmmoniaJson as unknown as StreamTable;
    expect(table.nodes.map((n) => n.id)).toContain("R1");
  });
});

