const BED_KEYS: (keyof ReactorBed)[] = ["catalyst_mass_kg", "catalyst_volume_m3", "outlet_temperature_K", "outlet_pressure_kPa", "pressure_drop_kPa", "hot_spot_K", "profile", "notes", "transport"];

describe("real /api/reactions of core's shift example (rate law, catalyst, fixed bed)", () => {
  const view = reactionsShiftJson as unknown as ReactionsView;
  const ammonia = reactionsJson as unknown as ReactionsView;
  it("uses only fields the viewer's types know", () => {
    expectKnown([view], REACTIONS_KEYS, "reactions");
    expectKnown(view.reactions, REACTION_KEYS, "reaction");
    expectKnown(view.reactions.map((r) => r.rate!), RATE_KEYS, "rate law");
    expectKnown(view.reactions.map((r) => r.rate!.k), ["A", "Ea", "n", "T_ref"], "Arrhenius");
    expectKnown(view.reactions.map((r) => r.rate_law!), RATE_VIEW_KEYS, "rate law view");
    expectKnown(view.reactions.flatMap((r) => r.rate_law!.k_profile), ["temperature_K", "k"], "k(T) point");
    expectKnown(view.reactors, REACTOR_KEYS, "reactor");
    expectKnown(view.reactors.flatMap((r) => (r.bed ? [r.bed] : [])), BED_KEYS, "bed");
    expectKnown(view.reactors.flatMap((r) => r.bed?.profile ?? []), ["catalyst_mass_kg", "temperature_K", "pressure_kPa"], "bed point");
    for (const v of [view, ammonia]) {
      expect(Object.keys(v.kinetics!)).toEqual(["file", "catalysts", "findings"]);
      expectKnown(v.kinetics!.catalysts, CATALYST_KEYS, "catalyst");
      expectKnown(v.kinetics!.catalysts.flatMap((c) => c.units), ["unit", "kind", "reactor", "reactions", "bed"], "catalyst unit");
      expectKnown(v.kinetics!.findings, FINDING_KEYS, "catalyst finding");
    }
    const cat = view.kinetics!.catalysts[0]!;
    expectKnown([cat.physical!], ["form", "particle_diameter", "sphericity", "particle_density", "bulk_density", "bed_voidage", "surface_area", "provenance", "source"], "physical");
    expectKnown([cat.window!], ["temperature", "pressure", "provenance", "source"], "window");
    expectKnown([cat.space_velocity!], ["basis", "range", "gas", "provenance", "source"], "space velocity");
    expectKnown([cat.deactivation!], ["lifetime", "mechanisms", "regeneration", "provenance", "source"], "deactivation");
    expectKnown([cat.price!], ["value", "unit", "year", "provenance", "source"], "price");
  });
  it("the WGS power law on FE_CR in the bed of R1", () => {
    const wgs = view.reactions[0]!;
    expect(wgs.rate?.form).toBe("power_law");
    expect(wgs.rate?.catalyst).toBe("FE_CR");
    expect(wgs.rate_law?.k_profile.length).toBe(21);
    expect(view.kinetics!.catalysts[0]!.reactions).toEqual(["WGS"]);
    expect(view.kinetics!.catalysts[0]!.units.map((u) => u.unit)).toEqual(["R1"]);
    const r1 = view.reactors.find((r) => r.node === "R1")!;
    expect(r1.bed!.profile.length).toBeGreaterThan(2);
  });
});

